package com.fintrack.controller; import com.fintrack.model.Transaction; import com.fintrack.repository.TransactionRepository; import com.fintrack.service.CurrentUser; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*; import java.util.stream.*;
@RestController @RequestMapping("/api/reports") public class ReportController{private final TransactionRepository repo;private final CurrentUser current;public ReportController(TransactionRepository r,CurrentUser c){repo=r;current=c;}@GetMapping("/summary")public Map<String,Object> summary(Authentication a){var tx=repo.findByUserIdOrderByTransactionDateDesc(current.get(a).getId());BigDecimal in=sum(tx,Transaction.TransactionType.INCOME),out=sum(tx,Transaction.TransactionType.EXPENSE),save=in.subtract(out);Map<String,BigDecimal> cat=tx.stream().filter(t->t.getType()==Transaction.TransactionType.EXPENSE).collect(Collectors.groupingBy(Transaction::getCategory,LinkedHashMap::new,Collectors.reducing(BigDecimal.ZERO,Transaction::getAmount,BigDecimal::add)));Map<String,Object> m=new LinkedHashMap<>();m.put("income",in);m.put("expense",out);m.put("savings",save);m.put("savingsRate",in.signum()==0?BigDecimal.ZERO:save.multiply(BigDecimal.valueOf(100)).divide(in,2,RoundingMode.HALF_UP));m.put("categoryBreakdown",cat);return m;}private BigDecimal sum(List<Transaction> t,Transaction.TransactionType type){return t.stream().filter(x->x.getType()==type).map(Transaction::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}}
